import type { AsmTask, BugTask, PickTask, Task, Unit } from './types.js'

const pick = (title: string, ctx: string, options: string[], correct: number, okText: string, badText: string, answer: string): PickTask => ({
  type: 'pick', title, ctx, options, correct, okText, badText, answer,
})

const assemble = (title: string, ctx: string, file: string, blocks: Record<string, string>, pool: string[], right: string[], okText: string, badText: string, answer: string): AsmTask => ({
  type: 'asm', title, ctx, file, blocks, pool, right, okText, badText, answer,
})

const bug = (title: string, ctx: string, file: string, lang: BugTask['lang'], lines: string[], correct: number, okText: string, badText: string, answer: string): BugTask => ({
  type: 'bug', title, ctx, file, lang, lines, correct, okText, badText, answer,
})

const unit = (id: string, title: string, sub: string, lessons: [string, Task[], Task[]][], project: Unit['project']): Unit => ({
  id, title, sub,
  nodes: [
    ...lessons.flatMap(([name, first, second], i) => {
      const l = { id: `${id}-${i + 1}`, kind: 'lesson' as const, name, tasks: [...first, ...second] }
      return i === 3 ? [{ id: `${id}-g`, kind: 'chest' as const, name: 'Сундук', xp: 20 }, l] : [l]
    }),
    {
      id: `${id}-p`,
      kind: 'project' as const,
      name: project.title,
      tasks: [
        pick('Как определить готовность проекта?', 'Проект: ' + project.title, ['Когда цель достигнута и результат можно показать или проверить', 'Когда добавлено как можно больше функций', 'Когда команда устала обсуждать его'], 0, 'Проект должен решать выбранную задачу, а результат — быть проверяемым.', 'Свяжи готовность с задачей пользователя и наблюдаемым результатом.', 'А — цель достигнута, результат проверяем'),
        pick('Что сделать перед тем, как показать результат?', 'Подготовь краткую демонстрацию своей работы.', ['Показать сценарий, результат и ограничения', 'Рассказывать только о потраченных часах', 'Скрыть места, которые ещё не работают'], 0, 'Хорошая демонстрация показывает, для кого сделан проект, как он работает и что ещё предстоит.', 'Покажи реальную пользу и честно обозначь границы решения.', 'А — сценарий, результат и ограничения'),
      ],
    },
  ],
  project,
})

